import json


class ImportProblem(Exception):
    def __init__(self, line):
        self.line = line
        super().__init__(f'invalid line {line}')


def _parse_line(raw, line):
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise ImportProblem(line)
    if text.endswith('\r'):
        text = text[:-1]
    try:
        record = json.loads(text)
    except ValueError:
        raise ImportProblem(line)
    record_id = record.get('id') if isinstance(record, dict) else None
    count = record.get('count') if isinstance(record, dict) else None
    if not isinstance(record, dict):
        raise ImportProblem(line)
    if not isinstance(record_id, str) or not record_id:
        raise ImportProblem(line)
    if not isinstance(count, int) or isinstance(count, bool):
        raise ImportProblem(line)
    return record


def import_bytes(payload, store):
    lines = payload.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    records = []
    for line, raw in enumerate(lines, 1):
        if not raw.strip():
            continue
        records.append(_parse_line(raw, line))
    store.records.extend(records)
    return len(records)

